/// <summary>
/// designed from AVA
/// </summary>
[ExtensionOf(formStr(CustTableLookup))]
internal final class AVACustTableLookupFrm_Extension
{
}

Method.Source:
/// <summary>
/// N.Freidenberger 14.08.24
/// </summary>
public void run()
{
    var args = this.args();

    if (this.args().caller() is FormRun)
    {
        FormRun             callerFormRun = this.args().caller();

        FormControl loccallingControl = SysTableLookup::getCallerControl(args);

        var formStringControl = loccallingControl as FormStringControl;
        if(callerFormRun && callerFormRun.name() == formStr(AVAKBVCreateRequestTable))
        {
            CustTable_ds.query().allowCrossCompany(true);
            CustTable_ds.query().addCompanyRange(this.args().parm());
        }

        if(callerFormRun && callerFormRun.name() == formStr(AVAKBVCreateRequestTable))
        {
            Query   basedQuery = new Query();
            int i;
            QueryBuildDataSource    custTableDS = basedQuery.addDataSource(tableNum(CustTable));
            basedQuery.allowCrossCompany(true);
            basedQuery.addCompanyRange(this.args().parm());


            QueryBuildDataSource    dirPartyTableDS = custTableDS.addDataSource(tablenum(DirPartyTable));
            dirPartyTableDS.relations(true);
            QueryBuildDataSource    logisticsPostalAddressDS =   dirPartyTableDS.addDataSource(tableNum(LogisticsPostalAddress));
            logisticsPostalAddressDS.relations(true);

            var absoluteFieldBinding = AbsoluteFieldBinding::construct(fieldStr(CustTable, AccountNum), tableStr(CustTable));
            var relationPath = RelationPath::constructFromPathString(tableStr(CustTable), 'DirPartyTable_FK');
            var relativeFieldBinding = RelativeFieldBinding::construct(fieldStr(DirPartyTable, NameAlias), relationPath);
            var resolver = new FormControlAmbiguousReferenceResolver(loccallingControl, absoluteFieldBinding, relativeFieldBinding,basedQuery);

            SysTableLookup::filterLookupPostRunEx(true, formStringControl.text(), custTable_AccountNum, custTable_ds,
                resolver, dirPartyTable_NameAlias, true);
        }
    }

    next run();

}

/// <summary>
/// N.Freidenberger 14.08.24
/// </summary>
void init()
{
    next init();
   // FormStringControl   callerControl = this.args().caller();
    if (this.args().caller() is FormRun)
    {
        FormRun             callerFormRun = this.args().caller();

        if(callerFormRun && callerFormRun.name() == formStr(AVAKBVCreateRequestTable))
        {
            CustTable_ds.query().allowCrossCompany(true);
            CustTable_ds.query().addCompanyRange(this.args().parm());
        }
    }
}
